playback/wave_player.crag.mlir:
// Wave Player
//
// A convenience wrapper around a crag.sampler that provides looping playback,
// start/stop gating, and end-of-file detection for audio wave files.
//
// The player reads from a sampler named "audio" and outputs a mono audio block
// each process() call.  Two events control gating:
//
//   start (void) — enable audio output (latch set)
//   stop  (void) — mute audio output  (latch reset)
//
// The player begins in the "playing" state (latch initialised to 1) so that
// audio flows immediately after a sampler asset is bound, without requiring
// an explicit start event.
//
// Looping:
//   When the `loop` parameter is ≥ 0.5 (i.e. treated as true), the read
//   position wraps modulo the bound asset length and crag.sample uses
//   per-sample modulo addressing so that blocks straddling the file boundary
//   are filled seamlessly from both the end and the beginning of the asset.
//   The result is gapless, click-free looping regardless of whether the asset
//   length is a multiple of the block size.
//
//   When `loop` < 0.5 the read position advances linearly and crag.sample
//   returns silence once the asset is exhausted — the natural end-of-file
//   condition.  The end-of-file is detected internally by comparing the
//   current frame position to the asset length; when it is reached the audio
//   output goes silent (no looping restart).
//
// Parameters:
//   loop  [0, 1]  — 1 = loop continuously, 0 = play once (default 1)
//
// Events:
//   start (void) — resume / un-mute playback
//   stop  (void) — pause / mute playback
//
// Sampler:
//   "audio" — bind a WAV file via crag_bind_audio_by_index(0, ptr, len)
//
// Output: !crag.audio<f32, 0, 1> — mono audio (or silence when muted / past end)
//
// Usage (after crag.include):
//   crag.include "standard-graphs/playback/wave_player.crag.mlir" as "wave_player"
//   ...
//   %audio = crag.subgraph_ref "wave_player"()
//                : () -> !crag.audio<f32, 0, 1>

module {
  crag.graph name = "wave_player" sample_rate = 0 channels = 1 {

    // -------------------------------------------------------------------------
    // Parameters
    // -------------------------------------------------------------------------
    %loop = crag.param "loop" min = 0.0 max = 1.0 default = 1.0 : f32

    // -------------------------------------------------------------------------
    // Events — start gates the output on, stop gates it off.
    // -------------------------------------------------------------------------
    %start_fired, %start_at = crag.event_void "start" : i1, i32
    %stop_fired,  %stop_at  = crag.event_void "stop"  : i1, i32

    // SR latch: set by "start", reset by "stop".
    // Initialised to 1 so playback begins immediately.
    %playing = crag.latch %start_fired, %stop_fired : i1, i1 -> i1
    %playing_f32 = arith.uitofp %playing : i1 to f32

    // -------------------------------------------------------------------------
    // Sampler
    // -------------------------------------------------------------------------
    %s   = crag.sampler "audio" : !crag.sampler<"audio">

    // Query the runtime asset length (in interleaved float samples).
    // Returns 0 when no asset is bound; we guard against zero-division below.
    %len = crag.sampler_length %s : !crag.sampler<"audio"> -> i64

    // -------------------------------------------------------------------------
    // Compute playback position
    // -------------------------------------------------------------------------
    %frame = crag.curframe : i64

    // Guard: replace a zero length with 1 to avoid division by zero.
    // (The resulting modulo is harmless because crag.sample will return silence
    // when no asset is bound regardless of the position.)
    %c0      = arith.constant 0   : i64
    %c1      = arith.constant 1   : i64
    %half    = arith.constant 0.5 : f32
    %len_ok  = arith.cmpi sgt, %len, %c0 : i64
    %safe_len = arith.select %len_ok, %len, %c1 : i64

    // Wrapped position for looping (block-aligned).
    %frame_mod = arith.remsi %frame, %safe_len : i64

    // Select between looping and one-shot position.
    %loop_on = arith.cmpf ogt, %loop, %half : f32
    %pos     = arith.select %loop_on, %frame_mod, %frame : i64

    // -------------------------------------------------------------------------
    // Read audio from the sampler
    // -------------------------------------------------------------------------
    // When looping, pass safe_len as the `end` argument so the lowering wraps
    // each sample index modulo the asset length, eliminating the silence gap
    // and skipped samples that would otherwise occur when a block straddles
    // the end of the audio file.  When not looping, pass 0 to keep the
    // existing behaviour of returning silence once the asset is exhausted.
    %wrap_len = arith.select %loop_on, %safe_len, %c0 : i64

    // Sampler output is pinned MONO (`<f32, 0, 1>`) rather than the
    // channel-agnostic `<f32, 0, 0>` placeholder.  Reason: the runtime audio
    // asset bound through `crag_bind_audio_by_index` is laid out as a flat,
    // interleaved-at-source-channels float buffer, and `crag.sample` reads
    // `blockSize * out_channels` consecutive samples starting at `pos`.  If
    // the output type were widened uniformly to the host engine's channel
    // count (e.g. 2 for a stereo engine), a mono wave file would be read at
    // *twice* the expected rate and re-interpreted as stereo interleaved —
    // producing playback at the wrong pitch with audible block-boundary
    // discontinuities, because `pos` advances by `blockSize` per block while
    // the sampler reads `2 * blockSize` samples (a 50%-overlap rewind every
    // block).  Pinning the interior to mono keeps `nSamp == blockSize` per
    // block (one source sample per output frame) and lets the engine's
    // `crag-inject-channel-mixers` pass upmix this mono signal to the host
    // channel count *at the wrapper boundary* — the same path
    // `mono_synth` / `random-wave` take.
    %audio_raw = crag.sample %s, %pos, %wrap_len
                     : !crag.sampler<"audio">, i64, i64
                       -> !crag.audio<f32, 0, 1>

    // -------------------------------------------------------------------------
    // Gate by playing state
    // -------------------------------------------------------------------------
    %audio = crag.scale %audio_raw, %playing_f32
                 : !crag.audio<f32, 0, 1>, f32 -> !crag.audio<f32, 0, 1>

    // -------------------------------------------------------------------------
    // Progress meter: normalized playback position [0, 1]
    // -------------------------------------------------------------------------
    %len_f32   = arith.sitofp %safe_len : i64 to f32
    %frame_f32 = arith.sitofp %frame_mod : i64 to f32
    %progress  = arith.divf %frame_f32, %len_f32 : f32
    crag.meter "progress" %progress min = 0.0 max = 1.0 : f32

    crag.output %audio : !crag.audio<f32, 0, 1>
  }
}

spatial/cipic/hrtf_spatializer_cipic.cra:
// HRTF Spatializer (CIPIC, fixed-position renderer)
//
// Dataset-driven HRTF spatializer variant.  Same ABI as
// `standard-graphs/spatial/hrtf_spatializer.crag.mlir` (mono in, binaural-
// tagged stereo out, position exposed via three `crag.param` ops) but the
// "tap + per-ear gain" middle of the naive reference is replaced with a
// pair of `crag.overlap_save_conv` ops convolving the dry input with the
// CIPIC-derived left/right HRIRs bound through the `--inline-sampler-data`
// flow.
//
// This first-pass renderer is **fixed-position**: each compiled binary
// corresponds to the HRIRs bound to `hrir_cipic_L` / `hrir_cipic_R` at
// compile time, which the `scripts/hrtf/render.py` driver picks from the
// normalized cache by index (default = front, az=0°, el=0°).  Runtime
// per-position IR selection / interpolation is now supported at
// the dialect level via the `crag.overlap_save_conv_slice` (runtime-
// offset/length partitioned-FFT variant) and `crag.tap_loop_conv`
// (direct-form FIR over a runtime IR window) ops; a follow-up renderer
// template will swap this fixed-position middle for one that takes a
// position index and slices a single concatenated-IR sampler.
//
// The position parameters are still declared and applied as a residual
// constant-power lateral pan + inverse-distance gain so hosts can drive
// the same parameter names regardless of which renderer is loaded.  When
// runtime per-position IR selection lands, the pan/distance math here
// will collapse into the IR-selection logic; for now they let the
// fixed-position renderer respond meaningfully to azimuth changes around
// the bound IR's "anchor" direction.
//
// Citation (per CIPIC's read_me.txt):
//   V. R. Algazi, R. O. Duda, D. M. Thompson, and C. Avendano,
//   "The CIPIC HRTF Database," Proc. 2001 IEEE Workshop on Applications
//   of Signal Processing to Audio and Acoustics (WASPAA'01),
//   pp. 99-102, New Paltz, NY, Oct. 2001.
//
// Sample rate: fixed at 48 kHz (CIPIC IRs are resampled from 44.1 kHz to
// 48 kHz by `scripts/hrtf/prep.py` before binding).
//
// IR length budget:
//   The normalized cache pads CIPIC IRs to 256 samples.  At
//   blockSize=512, a single OLS partition is enough to cover the full IR
//   without aliasing, so we set `num_partitions = 1` per ear.  If a
//   future cache schema bumps `ir_length` above 512, increase this
//   (and the renderer template will recompile transparently).
//
// Usage:
//   crag-compile \
//     --inline-sampler-data hrir_cipic_L:<...>_L_pos.wav \
//     --inline-sampler-data hrir_cipic_R:<...>_R_pos.wav \
//     standard-graphs/spatial/cipic/hrtf_spatializer_cipic.crag.mlir
//
// `scripts/hrtf/render.py` automates this against a packed cache entry.

module {
  // Position visualizer — see naive reference template comment.
  crag.include_visualizer "visualizers/spatial/position-combined.crag.mlir"
                          as "position_combined"

  crag.graph name = "hrtf_spatializer_cipic" sample_rate = 48000 channels = 1
      default_visualizer = "phase-correlation" {
  ^bb0(%in: !crag.audio<f32, 48000, 1>):

    // -----------------------------------------------------------------------
    // Position parameters (same ABI as the naive reference graph).
    // -----------------------------------------------------------------------
    %azimuth   = crag.param "azimuth_rad"
                     min = -3.14159274 max = 3.14159274 default = 0.0
                     unit = "rad" : f32
    %elevation = crag.param "elevation_rad"
                     min = -1.57079632 max = 1.57079632 default = 0.0
                     unit = "rad" : f32
    %distance  = crag.param "distance_m"
                     min = 0.1 max = 10.0 default = 1.0
                     unit = "m" : f32

    // -----------------------------------------------------------------------
    // Per-ear HRIR samplers.  At compile time, bind these via
    // --inline-sampler-data hrir_cipic_L:<L.wav>
    // --inline-sampler-data hrir_cipic_R:<R.wav>
    // -----------------------------------------------------------------------
    %ir_l = crag.sampler "hrir_cipic_L" : !crag.sampler<"hrir_cipic_L">
    %ir_r = crag.sampler "hrir_cipic_R" : !crag.sampler<"hrir_cipic_R">

    // -----------------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------------
    %one        = arith.constant 1.0 : f32
    %two        = arith.constant 2.0 : f32
    %dist_floor = arith.constant 0.1 : f32

    // -----------------------------------------------------------------------
    // Convolve the dry mono input with each ear's HRIR.
    //
    // num_partitions = 1: the cache caps `ir_length` at 256, well under the
    // default blockSize of 512, so one partition covers the IR without
    // aliasing.  Bumping the cache schema's IR length above blockSize
    // requires bumping this constant in tandem.
    // -----------------------------------------------------------------------
    %wet_l = crag.overlap_save_conv %in, %ir_l num_partitions = 1
                 : !crag.audio<f32, 48000, 1>,
                   !crag.sampler<"hrir_cipic_L">
                   -> !crag.audio<f32, 48000, 1>
    %wet_r = crag.overlap_save_conv %in, %ir_r num_partitions = 1
                 : !crag.audio<f32, 48000, 1>,
                   !crag.sampler<"hrir_cipic_R">
                   -> !crag.audio<f32, 48000, 1>

    // -----------------------------------------------------------------------
    // Residual constant-power lateral pan (sin(az)·cos(el)) so this
    // fixed-position renderer still tracks azimuth/elevation around the
    // bound IR's anchor direction.  Once runtime IR selection lands
    // this whole block is replaced by an IR-index computation.
    // -----------------------------------------------------------------------
    %sin_az    = math.sin %azimuth   : f32
    %cos_el    = math.cos %elevation : f32
    %pan       = arith.mulf %sin_az, %cos_el : f32

    %one_minus = arith.subf %one, %pan : f32
    %one_plus  = arith.addf %one, %pan : f32
    %gl_sq     = arith.divf %one_minus, %two : f32
    %gr_sq     = arith.divf %one_plus,  %two : f32
    %gl_pan    = math.sqrt %gl_sq : f32
    %gr_pan    = math.sqrt %gr_sq : f32

    // Inverse-distance with safe floor (matches the naive reference).
    %dist_safe = arith.maximumf %distance, %dist_floor : f32
    %dist_gain = arith.divf %one, %dist_safe : f32

    %gain_l    = arith.mulf %gl_pan, %dist_gain : f32
    %gain_r    = arith.mulf %gr_pan, %dist_gain : f32

    %out_l = crag.scale %wet_l, %gain_l
                 : !crag.audio<f32, 48000, 1>, f32 -> !crag.audio<f32, 48000, 1>
    %out_r = crag.scale %wet_r, %gain_r
                 : !crag.audio<f32, 48000, 1>, f32 -> !crag.audio<f32, 48000, 1>

    %binaural = crag.channel_join %out_l, %out_r
                    : (!crag.audio<f32, 48000, 1>, !crag.audio<f32, 48000, 1>)
                      -> !crag.audio<f32, 48000, 2, subtype = "binaural">

    // Position visualizer side-effect capture.
    crag.visualizer_ref "position_combined"(%in, %azimuth, %elevation, %distance)
        : (!crag.audio<f32, 48000, 1>, f32, f32, f32)

    crag.output %binaural : !crag.audio<f32, 48000, 2, subtype = "binaural">
  }
}
